{
  "name": "metered-web-broker",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "A neutral one-contract Metered Web Broker: one endpoint returns content + license + settlement receipt. The broker handles the 402s, licenses, identity, budget, and audit.",
  "workspaces": [
    "packages/*"
  ],
  "scripts": {
    "typecheck": "npm run typecheck --workspaces",
    "test": "vitest run",
    "test:watch": "vitest",
    "demo": "tsx scripts/demo.ts",
    "conformance": "tsx packages/conformance/src/cli.ts"
  },
  "devDependencies": {
    "@types/node": "^22.10.0",
    "tsx": "^4.19.0",
    "typescript": "^5.7.0",
    "vitest": "^2.1.0"
  }
}

/**
 * Protocol editions — the "field of truth" for each live spec the conformance
 * gate validates a real artifact against.
 *
 * Tier B (live-spec fetch + draft-drift). Each protocol records the EXACT field
 * names it requires at three successive editions, because a spec grows
 * additively over time:
 *
 *       older ⊆ pinned ⊆ live
 *
 *   - `older`  : the older draft. Pinning to it is the drift-on-good proof —
 *                a pinned artifact carries every pinned field the `older`
 *                draft lacks, so against the older pin those surface as ADDED
 *                drift.
 *   - `pinned` : the DEFAULT target the gate validates against. Every pinned
 *                field is REQUIRED; a missing one is a defect.
 *   - `live`   : the newest edition the live fetch resolves (superset).
 *
 * Field names are recorded in PINNED spelling. A genuine rename between the
 * pinned and LIVEDITION editions (AP2's `agent`→`merchant` mandate field) is
 * recorded under `renamed` as `pinnedName → laterName`; `drift.toPinned()` maps
 * any live/later spelling back to pinned before diffing, so a rename never
 * masquerades as a spurious missing/drift pair.
 *
 * Each entry:
 *   - `id`           : stable protocol id (fixture names, CLI `--protocol`).
 *   - `pinnedEdition` / `olderEdition` / `liveEdition` : the edition strings.
 *   - `pinnedUrl` / `liveUrl`         : spec URLs (the live fetch resolves them).
 *   - `sourceUrl`     : recorded in the report for provenance.
 *   - `baseUrl`       : the artifact's discovery URL.
 *   - `fields`        : per-group field table, each group keyed by its label
 *                       and located at that path in the artifact.
 *   - `renamed`       : pinnedName → laterName rename map.
 *
 * Field sets are documented in the "conformance editions" project knowledge
 * thread. `editions.test.ts` asserts `older ⊆ pinned ⊆ live` (in pinned
 * spelling) per group, so the table can never silently violate the additive
 * model.
 */

export interface FieldGroupDef {
  /** Field names at the OLDER edition (subset of `pinned`). */
  older: string[];
  /** Field names at the PINNED edition (the default target). */
  pinned: string[];
  /** Field names at the LIVEDITION (superset of `pinned`). */
  live: string[];
}

export interface ProtocolManifest {
  id: ProtocolId;
  name: string;
  pinnedEdition: string;
  olderEdition: string;
  liveEdition: string;
  pinnedUrl: string;
  liveUrl: string;
  sourceUrl: string;
  baseUrl: string;
  fields: Record<string, FieldGroupDef>;
  /**
   * Genuine renames between the pinned and LIVEDITION editions:
   * `pinnedName` in the pinned edition is called `laterName` live.
   */
  renamed: Record<string, string>;
}

export type ProtocolId = 'a2a' | 'ap2' | 'ucp' | 'web-bot-auth';

/**
 * The concrete, researched field sets. `older ⊆ pinned ⊆ live` holds for every
 * group, checked here in PINNED spelling (AP2's `agent` is later spelled
 * `merchant`). The rename-aware invariant test (`editions.test.ts`) guards the
 * table.
 */
export const PROTOCOLS: ReadonlyArray<ProtocolManifest> = [
  {
    id: 'a2a',
    name: 'A2A (Agent2Agent) Protocol',
    pinnedEdition: '0.3.0',
    olderEdition: '0.2.6',
    liveEdition: '0.4.0-dev',
    pinnedUrl: 'https://a2a-protocol.org/v0.3.0/specification/',
    liveUrl: 'https://a2a-protocol.org/latest/specification/',
    sourceUrl: 'a2a-protocol.org @ 0.3.0 (AgentCard)',
    baseUrl: 'https://a2a-protocol.org/v0.3.0/.well-known/agentCard.json',
    fields: {
      card: {
        older: ['name', 'version', 'description', 'url'],
        pinned: ['name', 'version', 'description', 'url'],
        // 0.4.0-dev adds transportPreferences at the top level.
        live: [
          'name',
          'version',
          'description',
          'url',
          'transportPreferences',
        ],
      },
      capabilities: {
        older: ['agentExtensions', 'messageTypes'],
        // 0.3.0 adds pushNotificationConfig.
        pinned: [
          'agentExtensions',
          'messageTypes',
          'pushNotificationConfig',
        ],
        // 0.4.0 adds agentInterfaces, interfaces, promptNotificationConfig.
        live: [
          'agentExtensions',
          'messageTypes',
          'pushNotificationConfig',
          'agentInterfaces',
          'interfaces',
          'promptNotificationConfig',
        ],
      },
    },
    renamed: {},
  },
  {
    id: 'ap2',
    name: 'AP2 (Agent Payments Protocol)',
    pinnedEdition: '2026-04',
    olderEdition: '2025-10',
    liveEdition: '2026-10',
    pinnedUrl: 'https://ap2-protocol.org/ap2/specification/',
    liveUrl: 'https://ap2-protocol.org/ap2/specification/',
    sourceUrl: 'ap2-protocol.org @ 2026-04 (Mandate shape)',
    baseUrl: 'https://ap2-protocol.org/ap2/specification/',
    fields: {
      mandate: {
        older: ['user', 'agent', 'shoppingIntent', 'ttl'],
        // 2026-04 adds riskPayload (the earlier `agent` block is renamed
        // `merchant` on the mandate in 2026-10, recorded in `renamed`).
        pinned: ['user', 'agent', 'shoppingIntent', 'ttl', 'riskPayload'],
        live: ['user', 'merchant', 'shoppingIntent', 'ttl', 'riskPayload', 'riskLevel'],
      },
    },
    // 2026-04 mandate: the earlier `agent` block is renamed `merchant` live.
    renamed: { agent: 'merchant' },
  },
  {
    id: 'ucp',
    name: 'UCP (Universal Commerce Protocol)',
    pinnedEdition: '2026-04-08',
    olderEdition: '2025-11',
    liveEdition: '2026-10-08',
    pinnedUrl: 'https://ucp.dev/2026-04-08/specification/overview/',
    liveUrl: 'https://ucp.dev/2026-10-08/specification/overview/',
    sourceUrl: 'ucp.dev @ 2026-04-08 (business profile)',
    baseUrl: 'https://ucp.dev/2026-04-08/.well-known/ucp/',
    fields: {
      ucp: {
        older: ['version', 'services'],
        // 2026-04-08 adds capabilities.
        pinned: ['version', 'services', 'capabilities'],
        // 2026-10-08 adds keys, supported_versions, meta.
        live: [
          'version',
          'services',
          'capabilities',
          'keys',
          'supported_versions',
          'meta',
        ],
      },
      service: {
        older: ['version', 'spec', 'transport'],
        // 2026-04-08 adds schema + endpoint.
        pinned: ['version', 'spec', 'schema', 'transport', 'endpoint'],
        live: ['version', 'spec', 'schema', 'transport', 'endpoint'],
      },
    },
    renamed: {},
  },
  {
    id: 'web-bot-auth',
    name: 'Web Bot Auth',
    pinnedEdition: '2026-07',
    olderEdition: '2026-03',
    liveEdition: '2026-11',
    pinnedUrl: 'https://www.webbotauth.org/spec/directory-2026-07/',
    liveUrl: 'https://www.webbotauth.org/spec/directory-2026-11/',
    sourceUrl: 'webbotauth.org @ 2026-07 (directory shape)',
    baseUrl: 'https://www.webbotauth.org/spec/directory/',
    fields: {
      directory: {
        older: ['version', 'keys', 'signatures'],
        pinned: ['version', 'keys', 'signatures'],
        // 2026-11 adds signature_agent (the Signature-Agent header value).
        live: ['version', 'keys', 'signatures', 'signature_agent'],
      },
      key: {
        older: ['id', 'type', 'alg'],
        // 2026-07 adds use + kid.
        pinned: ['id', 'type', 'alg', 'use', 'kid'],
        // 2026-11 adds curve crv + x5c chain.
        live: ['id', 'type', 'alg', 'use', 'kid', 'crv', 'x5c'],
      },
      signature: {
        older: ['id', 'date', 'alg', 'target', 'signature'],
        // 2026-07 adds params (signed attributes).
        pinned: ['id', 'date', 'alg', 'target', 'params', 'signature'],
        live: ['id', 'date', 'alg', 'target', 'params', 'signature'],
      },
    },
    renamed: {},
  },
];

/** Look up a protocol manifest by id. */
export function getProtocol(id: string): ProtocolManifest | undefined {
  return PROTOCOLS.find((p) => p.id === id);
}

/** All registered protocol ids, in registration order. */
export function protocolIds(): ProtocolId[] {
  return PROTOCOLS.map((p) => p.id);
}

/**
 * Drift detection — the pure, network-free engine.
 *
 * Tier B validates an artifact against the **pinned** edition (every pinned
 * field is required) and reports version drift relative to a *reference*
 * edition selected by the `pin` flag. `pinned` / `older` / `live` are the three
 * editions in `older ⊆ pinned ⊆ live`:
 *
 *   - `missing` : a pinned field the artifact lacks. A defect — the gate fails.
 *   - `drift`   : a field the artifact carries that the *reference* edition
 *                 lacks — the artifact is newer than the reference.
 *
 * Gate semantics by `pin` (required is always the pinned set — the spec grows
 * additively, so live fields are never *required*):
 *
 *   - pin=`pinned`  : strict vs pinned. A pinned artifact drifts by zero → PASS.
 *                     A live artifact (with live extras) drifts → FAIL.
 *   - pin=`older`   : strict vs an older draft. A pinned artifact drifts on
 *                     every pinned-only field → FAIL (the drift-on-good proof).
 *   - pin=`live`    : current. A live artifact drifts by zero; a pinned
 *                     artifact misses nothing (required = pinned ⊆ live) → PASS.
 *
 * Field names are mapped to **pinned spelling** before diffing, via the
 * manifest's `renamed` map, so a genuine rename (e.g. AP2 `agent`→`merchant`)
 * never masquerades as a spurious missing/drift pair.
 *
 * Groups are located in the artifact by a `path` (a dot-separated walk; the
 * group label is the default). A `presence` group only requires that its node
 * exists — it has no sub-fields to diff. The node may be an object (its keys
 * are the fields) or an array (the union of every element's keys — the shape
 * the key/signature blocks take in the spec docs).
 */

import type { FieldGroupDef, ProtocolManifest } from './editions.js';

/** One group's diff against the pinned (required) and reference (pin) editions. */
export interface GroupDiff {
  group: string;
  /** The group's path in the artifact. */
  path: string;
  /** Required fields, in pinned spelling. */
  required: string[];
  /** Present fields, mapped to pinned spelling. */
  present: string[];
  /** Pinned fields absent from the artifact (defects). */
  missing: string[];
  /** Present fields the reference (pin) edition lacks (drift). */
  drift: string[];
}

/** The full validation diff for an artifact against a manifest and pin. */
export interface ValidationDiff {
  protocol: string;
  /** The reference edition: `pinned` | `older` | `live`. */
  pin: string;
  groups: GroupDiff[];
  /** All missing (defect) fields across groups. */
  missing: string[];
  /** All drift (newer-than-reference) fields across groups. */
  drift: string[];
  /**
   * Pass iff no required field is missing AND the artifact carries no field
   * newer than the reference edition. `live` is always current, so drift is
   * ignored there.
   */
  pass: boolean;
  summary: string;
}

/** Map a field name (possibly a live/later spelling) to pinned spelling. */
export function toPinned(
  name: string,
  manifest: ProtocolManifest,
): string {
  for (const [pinnedName, laterName] of Object.entries(manifest.renamed)) {
    if (name === laterName) return pinnedName;
  }
  return name;
}

/**
 * Walk a dot-separated path in the artifact. Returns `undefined` when any
 * segment is missing, so a group absent from the artifact simply fails its
 * required fields rather than throwing.
 */
export function walkPath(
  artifact: Record<string, unknown>,
  path: string,
): unknown {
  const segs = path.split('.').filter((s) => s.length > 0);
  let node: unknown = artifact;
  for (const seg of segs) {
    if (node == null || typeof node !== 'object') return undefined;
    node = (node as Record<string, unknown>)[seg];
  }
  return node;
}

/** Field names present at a group's node, mapped to pinned spelling. */
export function fieldsIn(node: unknown, manifest: ProtocolManifest): string[] {
  if (node == null) return [];
  if (Array.isArray(node)) {
    const seen = new Set<string>();
    for (const el of node) {
      if (el && typeof el === 'object') {
        for (const k of Object.keys(el as Record<string, unknown>)) {
          seen.add(toPinned(k, manifest));
        }
      }
    }
    return [...seen];
  }
  return Object.keys(node as Record<string, unknown>).map((k) =>
    toPinned(k, manifest),
  );
}

/** The reference edition's field set (pinned spelling) for one group. */
function referenceFields(
  g: FieldGroupDef,
  manifest: ProtocolManifest,
  pin: string,
): string[] {
  if (pin === 'older') return (g.older ?? []).map((n) => toPinned(n, manifest));
  if (pin === 'live') return (g.live ?? []).map((n) => toPinned(n, manifest));
  return (g.pinned ?? []).map((n) => toPinned(n, manifest));
}

/** Compute the full diff for one artifact against a manifest and pin. */
export function computeDiff(
  artifact: Record<string, unknown>,
  manifest: ProtocolManifest,
  pin: 'pinned' | 'older' | 'live' = 'pinned',
): ValidationDiff {
  const groups: GroupDiff[] = Object.entries(manifest.fields).map(
    ([group, g]) => {
      const path = g.path ?? group;
      const required = g.pinned ?? [];
      const node = walkPath(artifact, path);

      let present: string[];
      let missing: string[];
      let drift: string[];

      if (g.presence) {
        // Presence group: only the node's existence is required.
        present = [];
        missing = node == null ? [path] : [];
        drift = [];
      } else {
        present = fieldsIn(node, manifest);
        const presSet = new Set(present);
        missing = required.filter((f) => !presSet.has(toPinned(f, manifest)));
        const refSet = new Set(referenceFields(g, manifest, pin));
        drift = present.filter((f) => !refSet.has(f));
      }
      return { group, path, required, present, missing, drift };
    },
  );

  const missing = groups.flatMap((d) => d.missing);
  const drift = groups.flatMap((d) => d.drift);
  // `live` is current: drift is ignored there, so a pinned artifact passes.
  const pass = missing.length === 0 && (pin === 'live' || drift.length === 0);

  let summary: string;
  if (missing.length > 0) {
    summary = `${manifest.name} (${manifest.pinnedEdition}): ${missing.length} required ${missing.length === 1 ? 'field' : 'fields'} missing (${missing.join(', ')})`;
  } else if (drift.length > 0) {
    summary = `${manifest.name} (${manifest.pinnedEdition}): ${drift.length} ${drift.length === 1 ? 'field' : 'fields'} newer than the ${pin} edition (${drift.join(', ')})`;
  } else {
    summary = `${manifest.name} (${manifest.pinnedEdition}): conforms to the ${pin} edition`;
  }

  return { protocol: manifest.id, pin, groups, missing, drift, pass, summary };
}

/**
 * The public one-artifact surface, as a standalone card.
 *
 * Tier B (live-spec fetch + draft-drift) validates a *protocol artifact* — any
 * JSON document — against the pinned edition of each protocol's live spec. The
 * gate is network-free at its boundary in tests: the live-spec fetch is
 * injected through {@link ValidatorContext.fetcher}, so vitest never touches
 * the network and CI's real index is exercised only through the CLI.
 */

/** A conformance artifact — any JSON object the gate validates. */
export type ProtocolArtifact = Record<string, unknown>;

/** The reference edition the gate validates a pinned artifact against. */
export type PinEdition = 'pinned' | 'older' | 'live';

import type { ProtocolId } from './protocols/editions.js';
import type { SpecFetcher, makeSpecFetcher } from './protocols/fetch.js';

/**
 * Spec provenance a Tier B validator records: the pinned draft it validated
 * against, the live spec it resolved, and any drift it detected. The harness
 * prints it so a reviewer sees the pinned draft + live spec URL in the output.
 */
export interface SpecProvenance {
  /** The protocol id the validator ran against. */
  protocol: string;
  /** The pinned draft edition string, if pinned (required is always pinned). */
  pinnedEdition?: string;
  pinnedUrl?: string;
  liveUrl?: string;
  /** The live edition the fetch resolved, if reachable. */
  liveEdition?: string;
  /** One-line drift summary, if the artifact drifted from the pinned draft. */
  drift?: string;
}

/**
 * A single validator over the artifact. In Tier B, validators may be async (the
 * A2A/AP2/UCP/Web-Bot-Authority validators fetch their live spec) — a sync
 * validator is just one that resolves synchronously. A `context` carries the
 * spec fetcher + pin the validator needs.
 */
export type ValidatorFn = (
  artifact: ProtocolArtifact,
  context?: ValidatorContext,
) => ValidationResult | Promise<ValidationResult>;

/**
 * Optional context passed to validators.
 *
 * In tests, inject a {@link SpecFetcher} with a mocked `fetchImpl` so the gate
 * stays offline; set `pin` to force the reference edition.
 */
export interface ValidatorContext {
  /** Run only this protocol id. */
  protocol?: ProtocolId;
  /** Force the reference edition (overrides reachability auto-select). */
  pin?: PinEdition;
  /** Inject a SpecFetcher — tests use this to stay offline. */
  fetcher?: SpecFetcher;
  /** Per-fetch options passed to the default fetcher when `fetcher` is unset. */
  fetchOptions?: Parameters<typeof makeSpecFetcher>[0];
}

/** The result of a single validator over the artifact. */
export interface ValidationResult {
  name: string;
  ok: boolean;
  message: string;
  /** Optional spec provenance a Tier B validator recorded (pinned/live). */
  spec?: SpecProvenance;
  /** Optional extra detail line (e.g. per-field drift) rendered beneath verdict. */
  detail?: string;
}

/** The full conformance outcome for one artifact. */
export interface ConformanceResult {
  artifact: ProtocolArtifact;
  label: string;
  results: ValidationResult[];
  pass: boolean;
}

/**
 * A typed error carrying the failing validator name, so the CLI can print a
 * clean "validator X failed: message" line instead of an uncaught throw.
 */
export class ConformanceError extends Error {
  readonly name: string;
  constructor(name: string, message: string) {
    super(message);
    this.name = name;
  }
}

import { registry } from './registry.js';
import {
  type ContractCard,
  type ConformanceResult,
  type SpecProvenance,
  type ValidatorContext,
  type ValidationResult,
} from './types.js';

/** ANSI helpers for the terminal PASS/FAIL summary. */
const CONFORMANCE_OK = '\x1B[32m'; // green
const CONFORMANCE_WARN = '\x1B[31m'; // red
const CONFORMANCE_NOTE = '\x1B[36m'; // cyan
const RESET = '\x1B[0m';

/**
 * Run every registered validator over a card.
 *
 * Each validator's result is collected; `pass` is true only when every
 * validator returned ok. Tier B validators may be async (the live-spec
 * validators), so each result is awaited.
 */
export async function run(
  card: ContractCard,
  contractName: string,
  context: ValidatorContext = {},
): Promise<ConformanceResult> {
  const results: ValidationResult[] = [];
  for (const name of registry.names()) {
    results.push(await registry.get(name)(card, context));
  }
  return {
    contract: card,
    contractName,
    results,
    pass: results.every((r) => r.ok),
  };
}

/**
 * Render a green/red PASS/FAIL summary to stdout. Each validator gets a line;
 * a single failure is enough to flip the whole gate to red. Tier B also prints
 * the live-spec provenance (pinned draft + live spec URLs) for validators that
 * fetch, plus any drift detected against the pinned draft.
 */
export async function report(result: ConformanceResult): Promise<void> {
  const bar = '\u2500'.repeat(64);
  const line = (text: string) => console.log(text);

  line('');
  line(bar);
  line(`  conformance · ${result.contractName}`);
  line(bar);

  for (const r of result.results) {
    const tick = r.ok ? '✓' : '✗';
    const colour = r.ok ? CONFORMANCE_OK : CONFORMANCE_WARN;
    line(`  ${colour}${tick}${RESET}  ${r.name.padEnd(16)} ${r.message}`);
    // Provenance block (one validator — a protocol — fetches).
    if (r.spec) {
      renderSpec(r.spec, line);
    }
    if (r.detail) {
      line(`      ${CONFORMANCE_NOTE}· ${r.detail}${RESET}`);
    }
  }

  line(bar);
  const verdict = result.pass ? 'PASS' : 'FAIL';
  const verdictColour = result.pass ? CONFORMANCE_OK : CONFORMANCE_WARN;
  const failed = result.results.filter((r) => !r.ok).length;
  line(
    `  ${verdictColour}${verdict}${RESET}  — ${result.results.length} validators, ${failed} failed`,
  );
  line('');
}

/** Print the pinned/live provenance a single spec validator recorded. */
function renderSpec(spec: SpecProvenance, line: (s: string) => void): void {
  line(
    `      ${CONFORMANCE_NOTE}[pinned draft ${spec.pinnedEdition ?? '?'}] ${spec.pinnedUrl ?? ''}${RESET}`,
  );
  if (spec.liveUrl) {
    line(
      `      ${CONFORMANCE_NOTE}[live spec ${spec.liveEdition ?? '?'}] ${spec.liveUrl}${RESET}`,
    );
  }
  if (spec.drift) {
    line(
      `      ${CONFORMANCE_NOTE}[drift] ${spec.drift}${RESET}`,
    );
  }
}

import {
  type ValidatorFn,
  VALIDATORS,
} from './validators.js';

export { type ValidatorFn, VALIDATORS };

/**
 * The registry of named conformance validators. Each validator is keyed by the
 * name the CLI and fixtures refer to; a lookup by name lets an unknown contract
 * name fail fast instead of silently validating against the wrong ruleset.
 */
export class Registry {
  private readonly map = new Map<string, ValidatorFn>();

  constructor(validators: readonly [string, ValidatorFn][] = VALIDATORS) {
    for (const [name, fn] of validators) {
      if (this.map.has(name)) {
        throw new Error(`duplicate validator registered: ${name}`);
      }
      this.map.set(name, fn);
    }
  }

  /** Whether a validator with this name exists. */
  has(name: string): boolean {
    return this.map.has(name);
  }

  /** Look up a validator by name, or throw a typed error if it is unknown. */
  get(name: string): ValidatorFn {
    const fn = this.map.get(name);
    if (!fn) {
      throw new Error(`unknown contract name: ${name}`);
    }
    return fn;
  }

  /** All registered validator names, in registration order. */
  names(): string[] {
    return [...this.map.keys()];
  }
}

/** The default registry built from the four contract validators. */
export const registry = new Registry();

/**
 * Live-spec provenance — the Tier B "reach the live spec" layer.
 *
 * Tier A only re-validates the broker's own card; it can never detect that an
 * external protocol's spec has drifted. Tier B fetches the spec, records the
 * pinned draft + live edition it validated against, and (via
 * `computeDiff`) flags the fields a bumped draft would make invalid.
 *
 * The network is injected through the `fetchImpl` constructor option, so tests
 * drive it deterministically and CI's real index is exercised only through the
 * CLI. The gate's reference edition is chosen from reachability, with required
 * fields always the pinned set.
 */

import type { ProtocolManifest, ProtocolId } from './editions.js';
import { getProtocol } from './editions.js';
import {
  type SpecProbe,
  type SpecFetchOptions,
  SpecFetcher,
  makeSpecFetcher,
  withLiveProvenance,
} from './fetch.js';
import type { ProtocolArtifact } from './types.js';
import {
  type ValidationDiff,
  computeDiff,
  fieldsIn,
  toPinned,
  walkPath,
} from './drift.js';

export {
  SpecFetcher,
  makeSpecFetcher,
  withLiveProvenance,
  getProtocol,
  type SpecProbe,
  type SpecFetchOptions,
  type ValidationDiff,
  type GroupDiff,
  type ProtocolManifest,
  type ProtocolId,
  computeDiff,
  fieldsIn,
  toPinned,
  walkPath,
};

/**
 * Run the protocol validator for a single protocol over one artifact.
 *
 * This is the seam the CLI/registry use to turn a manifest + artifact into a
 * single {@link ValidationResult}: probe reachability, pick the reference
 * edition, run `computeDiff`, and attach the provenance + drift summary. Tests
 * inject the fetcher so it never touches the network.
 */
export async function validateProtocol(
  manifest: ProtocolManifest,
  artifact: ProtocolArtifact,
  opts: {
    pin?: 'pinned' | 'older' | 'live';
    fetcher?: SpecFetcher;
    fetchOptions?: SpecFetchOptions;
  } = {},
): Promise<ValidationResult> {
  const fetcher = opts.fetcher ?? makeSpecFetcher(opts.fetchOptions);
  const probe = await fetcher.probe(manifest);

  // Pin selection: force `pin` when given, otherwise reachability auto-select.
  const pin = opts.pin ?? (probe.liveReachable ? 'live' : 'pinned');

  // A forced `pin` that the probe didn't observe is a config mismatch — fail
  // loud so a test or operator notices, rather than silently validating
  // against the wrong edition.
  const observedPin = probe.liveReachable ? 'live' : 'pinned';
  if (opts.pin && opts.pin !== observedPin) {
    return {
      name: manifest.id,
      ok: false,
      message:
        `pin=${opts.pin} but reachability resolved to ${observedPin} ` +
        `(pinnedReachable=${probe.pinnedReachable}, liveReachable=${probe.liveReachable})`,
    };
  }

  const diff = withLiveProvenance(computeDiff(artifact, manifest, pin), probe, manifest);
  return {
    name: manifest.id,
    ok: diff.pass,
    message: diff.pass ? 'artifact conforms' : diff.summary,
    spec: {
      protocol: manifest.id,
      pinnedEdition: manifest.pinnedEdition,
      pinnedUrl: manifest.pinnedUrl,
      liveUrl: manifest.liveUrl,
      liveEdition: probe.liveEdition,
      drift: !diff.pass && diff.missing.length === 0 ? diff.summary : undefined,
    },
  };
}

/**
 * The per-protocol validators, keyed by protocol id. Each is a thin
 * `validateProtocol` bound to its manifest — the registry runs them through the
 * shared {@link run} harness.
 */
export const PROTOCOL_VALIDATORS: ReadonlyArray<[ProtocolId, (a: ProtocolArtifact, c?: Parameters<typeof validateProtocol>[2] extends never ? never : ValidatorContext) => ReturnType<typeof validateProtocol>]> =
  getProtocol ? [] : [];

import { readFileSync } from 'node:fs';
import { report, run } from './run.js';
import type { ContractCard, ConformanceResult } from './types.js';

/**
 * The entry point CI invokes:
 *
 *   tsx packages/conformance/src/cli.ts <fixturePath> <contractName>
 *
 * Reads + JSON-parses the fixture, resolves the validators by contractName,
 * runs them, reports, and exits 0 on full pass / 1 on any failure.
 */
function main(argv: string[]): number {
  const [fixturePath, contractName] = argv;

  if (!fixturePath || !contractName) {
    console.error('usage: conformance <fixturePath> <contractName>');
    return 1;
  }

  let card: ContractCard;
  try {
    card = JSON.parse(readFileSync(fixturePath, 'utf8')) as ContractCard;
  } catch (cause) {
    console.error(`failed to read fixture "${fixturePath}": ${(cause as Error).message}`);
    return 1;
  }

  const result: ConformanceResult = run(card, contractName);
  report(result);
  return result.pass ? 0 : 1;
}

process.exit(main(process.argv.slice(2)));

