/**
 * Live-spec provenance — the Tier B "reach the live spec" layer.
 *
 * Tier A only re-validates the broker's own card; it can never detect that an
 * external protocol's spec has drifted. Tier B fetches the spec, records the
 * pinned draft + live edition it validated against, and (via
 * `computeDiff`) flags the fields a bumped draft would make invalid.
 *
 * This module is deliberately network-free at the boundary: the actual `fetch`
 * is injected (via `makeSpecFetcher({ fetchImpl })`), so tests drive it
 * deterministically and CI never depends on the live index at all.
 *
 * The gate's reference edition is chosen from reachability:
 *   - pinned reachable  → validate against `pinned` (the drift-on-good fixture
 *                         proves a pinned artifact drifts against `older`).
 *   - pinned gone, live reachable → fall back to `live` so a draft that is no
 *     longer pinned doesn't false-fail every artifact.
 *
 * Required fields are ALWAYS the pinned set (the model is additive: live
 * extras are never *required*).
 */

import type { ValidationDiff } from './drift.js';
import { computeDiff } from './drift.js';
import type { ProtocolManifest } from './editions.js';

/** A single URL hit: whether we got it, and its HTTP status, if we got one. */
export interface HitResult {
  /** True iff we got an HTTP 2xx. */
  ok: boolean;
  /** HTTP status, if a response was received at all. */
  status?: number;
  /** The reason it failed (thrown response, network error, timeout). */
  error?: string;
}

/** Reachability + the resolved live edition for a protocol's spec. */
export interface SpecProbe {
  pinnedUrl: string;
  liveUrl: string;
  /** True iff the pinned draft URL returns 2xx. */
  pinnedReachable: boolean;
  /** True iff the live (latest) URL returns 2xx. */
  liveReachable: boolean;
  pinnedStatus?: number;
  liveStatus?: number;
  /** The newest edition the live pointer is known to resolve to. */
  liveEdition?: string;
}

/** Options for the live-spec fetch/probe. */
export interface SpecFetchOptions {
  /** Abort a hit after this many ms. Defaults to 8000. */
  timeoutMs?: number;
  /**
   * The fetch used for every hit. Inject in tests. Defaults to
   * `globalThis.fetch`.
   */
  fetchImpl?: typeof fetch;
  /** HTTP method to hit the spec with. Defaults to 'GET'. */
  method?: 'GET' | 'HEAD';
}

/**
 * The live-spec fetcher: probes a manifest's pinned + live spec URLs, picks the
 * reference edition from reachability, and runs drift detection against it.
 */
export class SpecFetcher {
  private readonly timeoutMs: number;
  private readonly fetchImpl: typeof fetch;
  private readonly method: 'GET' | 'HEAD';

  constructor(opts: SpecFetchOptions = {}) {
    this.timeoutMs = opts.timeoutMs ?? 8000;
    this.method = opts.method ?? 'GET';
    const fetcher = opts.fetchImpl ?? (globalThis as { fetch?: typeof fetch })
      .fetch;
    if (!fetcher) {
      throw new Error('no fetch implementation available');
    }
    this.fetchImpl = fetcher;
  }

  /** Probe one URL, returning whether we got an HTTP 2xx and its status. */
  private async hit(url: string): Promise<HitResult> {
    try {
      const res = await this.fetchImpl(url, {
        method: this.method,
        redirect: 'follow',
        signal: AbortSignal.timeout(this.timeoutMs),
      });
      return { ok: res.ok, status: res.status };
    } catch (cause) {
      const err = cause as { name?: string; message?: string };
      return {
        ok: false,
        error: err.name ?? 'unknown',
      };
    }
  }

  /**
   * Probe a manifest: hit both URLs. Returns reachability and the resolved live
   * edition. `liveEdition` is `undefined` when the live pointer is unreachable,
   * so the gate falls back to `pinned`.
   */
  async probe(manifest: ProtocolManifest): Promise<SpecProbe> {
    const pinned = await this.hit(manifest.pinnedUrl);
    const live = await this.hit(manifest.liveUrl);
    return {
      pinnedUrl: manifest.pinnedUrl,
      liveUrl: manifest.liveUrl,
      pinnedReachable: pinned.ok,
      liveReachable: live.ok,
      pinnedStatus: pinned.status,
      liveStatus: live.status,
      liveEdition: live.ok ? manifest.liveEdition : undefined,
    };
  }

  /**
   * The reference edition for the gate, chosen from reachability:
   * `live` when the live pointer resolves, else `pinned`.
   */
  async referenceEdition(manifest: ProtocolManifest): Promise<'pinned' | 'live'> {
    const probe = await this.probe(manifest);
    return probe.liveReachable ? 'live' : 'pinned';
  }

  /**
   * Run the full gate for one manifest: probe, pick the reference edition, run
   * `computeDiff`, and attach the provenance + drift summary.
   */
  async validateArtifact(
    artifact: Record<string, unknown>,
    manifest: ProtocolManifest,
  ): Promise<ValidationDiff> {
    const probe = await this.probe(manifest);
    const pin = probe.liveReachable ? 'live' : 'pinned';
    return withLiveProvenance(computeDiff(artifact, manifest, pin), probe, manifest);
  }
}

/** Build a `SpecFetcher` from options (idiomatic constructor alias). */
export function makeSpecFetcher(opts: SpecFetchOptions = {}): SpecFetcher {
  return new SpecFetcher(opts);
}

/**
 * Attach the spec provenance + drift summary a probe discovered to a raw diff,
 * returning it unchanged. This is the seam the per-protocol validators use to
 * record what the gate actually validated against.
 */
export function withLiveProvenance(
  diff: ValidationDiff,
  probe: SpecProbe,
  manifest: ProtocolManifest,
): ValidationDiff {
  return {
    ...diff,
    summary:
      diff.summary +
      ` [pinned ${manifest.pinnedEdition} :: live ${probe.liveEdition ?? 'n/a'}]`,
  };
}

