/** Pinned/older field is covered by live up to renames. */
function covered(
  field: string,
  live: string[],
  renamed: Record<string, string>,
): boolean {
  if (live.includes(field)) return true;
  return renamed[field] !== undefined && Object.values(renamed).includes(renamed[field]);
}

