    const olderInPinned = set.older.every((x) => set.pinned.includes(x));
    const pinnedInLive = set.pinned.every((x) => covered(x, set.live, p.renamed));
    if (!olderInPinned || !pinnedInLive) {
      ok = false;
      console.log(`BAD ${p.id}.${g}: older⊆pinned=${olderInPinned} pinned⊆live=${pinnedInLive}`);
    }
  }
